// Brevo (formerly Sendinblue) on an API key: every operation in its published API v3. actions.json is generated by
// `bun scripts/openapi-actions.ts brevo`; email events start automations by webhook (triggers.ts).
import { z } from "zod";
import type { OwnApp } from "../index";
import { type Api, call, rest, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

export const api: Api = {
  name: "Brevo",
  base: "https://api.brevo.com/v3",
  tokenHelp: "app.brevo.com/settings/keys/api",
  auth: (key) => ({ "api-key": key, accept: "application/json" }),
};

// Brevo's spec points these bodies at schemas it leaves out, so their fields are written here (from its older spec)
const CONTACTS = {
  emails: z.array(z.string()).max(150).optional().describe("The contacts' email addresses (up to 150). Give this or ids"),
  ids: z.array(z.number().int()).max(150).optional().describe("The contacts' Brevo ids (up to 150), instead of emails"),
  extIds: z.array(z.string()).max(150).optional().describe("The contacts' EXT_ID attribute values (up to 150), instead of emails"),
};
const LIST_ID = z.number().int().describe("The list's id (get_contact_lists lists them)");
const byHand = {
  add_contacts_to_list: rest(api, "POST", "/contacts/lists/{listId}/contacts/add", "Add existing contacts to a list. To add someone new, use create_contact with listIds instead.", z.object({ listId: LIST_ID, ...CONTACTS })),
  remove_contacts_from_list: rest(
    api,
    "POST",
    "/contacts/lists/{listId}/contacts/remove",
    "Take contacts off a list (they stay in Brevo).",
    z.object({ listId: LIST_ID, ...CONTACTS, all: z.boolean().optional().describe("true: take everyone off the list (runs in the background; get_process shows progress)") }),
  ),
  send_whatsapp_message: rest(
    api,
    "POST",
    "/whatsapp/sendMessage",
    "Send a WhatsApp message from your Brevo WhatsApp number. Outside a 24-hour reply window WhatsApp only allows approved templates (templateId).",
    z.object({
      senderNumber: z.string().describe("Your WhatsApp number in Brevo, with country code and no +, like 919876543210"),
      contactNumbers: z.array(z.string()).describe("The people's numbers, with country code and no +, like 919876543210"),
      templateId: z.number().int().optional().describe("An approved WhatsApp template's id (list_whatsapp_templates)"),
      text: z.string().optional().describe("The message, when not sending a template"),
      params: z.record(z.string(), z.unknown()).optional().describe('Values for the template\'s placeholders, like {"FNAME": "Asha"}'),
    }),
  ),
  export_webhook_history: rest(
    api,
    "POST",
    "/webhooks/export",
    "Export a webhook's delivery history as a CSV; Brevo posts the file's link to notifyURL when it's ready.",
    z.object({
      type: z.enum(["transactional", "marketing"]).describe("Which webhooks"),
      event: z.string().describe("The event, like request, delivered, opened, click, hardBounce, or allEvents"),
      notifyURL: z.string().describe("Where Brevo sends the CSV's link"),
      days: z.number().int().optional().describe("The last this many days, including today (instead of startDate and endDate)"),
      startDate: z.string().optional().describe("From this day, YYYY-MM-DD"),
      endDate: z.string().optional().describe("To this day, YYYY-MM-DD"),
      sort: z.enum(["asc", "desc"]).optional().describe("Oldest or newest first"),
      webhookId: z.number().int().optional().describe("Only this webhook"),
      email: z.string().optional().describe("Only this email address"),
      messageId: z.string().optional().describe("Only this message (transactional)"),
    }),
  ),
};

export const brevo: OwnApp = {
  app: "brevo",
  name: "Brevo",
  logo: "/logos/brevo.svg",
  keyField: {
    label: "API key",
    help: "In Brevo: click your name → SMTP & API → API keys (app.brevo.com/settings/keys/api) → Generate a new API key, name it Emplio, then copy it. If Brevo only lets known IP addresses use your keys (Security → Authorised IPs), turn that off or Emplio's calls will be refused.",
    placeholder: "xkeysib-...",
  },
  async check(key) {
    const me = (await call(api, key, { method: "GET", path: "/account", query: [], headers: [] }, {})) as { companyName?: string; email?: string };
    return me.companyName || me.email;
  },
  push: {
    events,
    triggers,
    start: (key, connection, event, config) => watch(api, key, connection, event, config),
    stop: (key, id) => unwatch(api, key, id),
    receive,
    wanted,
  },
  actions: { ...(await specActions(new URL("./actions.json", import.meta.url), api)), ...byHand },
};
